-- Editorial and event domain. Depends on 010 (identity) and 020 (mail queue).
begin;
create table public.articles (id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),title text not null check(char_length(title) between 3 and 180),excerpt text not null check(char_length(excerpt) between 3 and 500),body text not null check(char_length(body) between 1 and 100000),tags text[] not null default '{}',status text not null default 'draft' check(status in('draft','published')),published_at timestamptz,seo_title text,seo_description text,author_id uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status='draft' and published_at is null) or status='published'));
create table public.events (id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),title text not null,description text not null,starts_at timestamptz not null,ends_at timestamptz,location text not null,organiser text not null,capacity integer check(capacity is null or capacity>0),registration_open boolean not null default false,published boolean not null default false,price_ore integer not null default 0 check(price_ore>=0),currency text not null default 'sek' check(currency='sek'),cancelled_at timestamptz,created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at));
create table public.event_registrations (id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,email text not null,name text not null,status text not null check(status in('confirmed','waitlisted','cancelled','payment_pending','refunded')),ticket_code text unique check(ticket_code is null or ticket_code ~ '^[A-Z0-9]{12}$'),checkout_session_id text unique,payment_intent_id text unique,reservation_expires_at timestamptz,checked_in_at timestamptz,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,email),check((status='confirmed' and ticket_code is not null) or status<>'confirmed'));
create table public.stripe_webhook_events(stripe_event_id text primary key,event_type text not null,received_at timestamptz not null default now(),processed_at timestamptz,payload jsonb not null);
create table public.event_practical_messages(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,request_id uuid not null,request_digest text not null check(request_digest ~ '^[a-f0-9]{64}$'),message text not null check(char_length(message) between 1 and 10000),created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now(),unique(event_id,request_id));
create index articles_public_idx on public.articles(published_at desc) where status='published'; create index events_public_idx on public.events(starts_at) where published and cancelled_at is null; create index event_registration_event_status_idx on public.event_registrations(event_id,status,reservation_expires_at);
create function public.set_editorial_events_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end $$;
create trigger articles_updated_at before update on public.articles for each row execute function public.set_editorial_events_updated_at(); create trigger events_updated_at before update on public.events for each row execute function public.set_editorial_events_updated_at(); create trigger event_registrations_updated_at before update on public.event_registrations for each row execute function public.set_editorial_events_updated_at();
create function public.enqueue_event_mail(k text,t text,r text,title text,slug text) returns void language plpgsql security definer set search_path='' as $$ begin perform public.enqueue_queue_mail(k,t,r,jsonb_build_object('reference',jsonb_build_object('type','event-registration','id',split_part(k,':',2)::uuid)),clock_timestamp(),null);end $$;
create function public.register_free_event(p_event_slug text,p_email text,p_name text,p_ticket_code text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare e public.events;r public.event_registrations;taken integer;begin select * into e from public.events where slug=p_event_slug for update;if not found or not e.published or not e.registration_open or e.cancelled_at is not null or e.starts_at<=clock_timestamp() or e.price_ore<>0 then raise exception 'registration_closed';end if;select * into r from public.event_registrations where event_id=e.id and email=lower(p_email) for update;if found then return r;end if;select count(*) into taken from public.event_registrations where event_id=e.id and status='confirmed';insert into public.event_registrations(event_id,email,name,status,ticket_code) values(e.id,lower(p_email),p_name,case when e.capacity is not null and taken>=e.capacity then 'waitlisted' else 'confirmed' end,case when e.capacity is not null and taken>=e.capacity then null else p_ticket_code end) returning * into r;perform public.enqueue_event_mail('event:'||r.id::text||':'||r.status,case when r.status='confirmed' then 'event-registration' else 'event-waitlist' end,r.email,e.title,e.slug);return r;end $$;
create function public.begin_paid_event_registration(p_event_slug text,p_email text,p_name text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare e public.events;r public.event_registrations;taken integer;begin select * into e from public.events where slug=p_event_slug for update;if not found or not e.published or not e.registration_open or e.cancelled_at is not null or e.starts_at<=clock_timestamp() or e.price_ore<=0 then raise exception 'registration_closed';end if;update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where event_id=e.id and status='payment_pending' and reservation_expires_at<=clock_timestamp();select * into r from public.event_registrations where event_id=e.id and email=lower(p_email) for update;if found and r.status in('confirmed','payment_pending','waitlisted') then return r;end if;select count(*) into taken from public.event_registrations where event_id=e.id and (status='confirmed' or(status='payment_pending' and reservation_expires_at>clock_timestamp()));insert into public.event_registrations(event_id,email,name,status,reservation_expires_at) values(e.id,lower(p_email),p_name,case when e.capacity is not null and taken>=e.capacity then 'waitlisted' else 'payment_pending' end,case when e.capacity is not null and taken>=e.capacity then null else clock_timestamp()+interval '30 minutes' end) on conflict(event_id,email) do update set name=excluded.name,status=excluded.status,reservation_expires_at=excluded.reservation_expires_at,cancelled_at=null returning * into r;if r.status='waitlisted' then perform public.enqueue_event_mail('event:'||r.id::text||':waitlisted','event-waitlist',r.email,e.title,e.slug);end if;return r;end $$;
create function public.attach_paid_checkout(p_registration_id uuid,p_checkout_session_id text) returns void language plpgsql security definer set search_path='' as $$ begin update public.event_registrations set checkout_session_id=p_checkout_session_id where id=p_registration_id and status='payment_pending' and checkout_session_id is null and reservation_expires_at>clock_timestamp();if not found then raise exception 'reservation_expired';end if;end $$;
create function public.process_paid_checkout(p_stripe_event_id text,p_registration_id uuid,p_checkout_session_id text,p_client_reference_id text,p_payment_intent_id text,p_amount integer,p_currency text,p_payload jsonb,p_ticket_code text) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations;e public.events;begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'checkout.session.completed',p_payload) on conflict do nothing;if not found then return;end if;select * into r from public.event_registrations where id=p_registration_id for update;if not found then raise exception 'checkout_mismatch';end if;select * into e from public.events where id=r.event_id for update;if r.id::text<>p_client_reference_id or r.checkout_session_id<>p_checkout_session_id or e.price_ore<>p_amount or e.currency<>p_currency or r.status<>'payment_pending' or r.reservation_expires_at<=clock_timestamp() then raise exception 'checkout_mismatch';end if;update public.event_registrations set status='confirmed',ticket_code=p_ticket_code,payment_intent_id=p_payment_intent_id,reservation_expires_at=null where id=r.id;perform public.enqueue_event_mail('event:'||r.id::text||':confirmed','event-registration',r.email,e.title,e.slug);update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id;end $$;
create function public.process_event_refund(p_stripe_event_id text,p_payment_intent_id text,p_payload jsonb) returns void language plpgsql security definer set search_path='' as $$ begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'charge.refunded',p_payload) on conflict do nothing;if not found then return;end if;update public.event_registrations set status='refunded' where payment_intent_id=p_payment_intent_id and status='confirmed';update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id;end $$;
create function public.check_in_event_ticket(p_ticket_code text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare r public.event_registrations;begin select * into r from public.event_registrations where ticket_code=p_ticket_code for update;if not found or r.status<>'confirmed' then raise exception 'ticket_invalid';end if;update public.event_registrations set checked_in_at=coalesce(checked_in_at,clock_timestamp()) where id=r.id returning * into r;return r;end $$;
create function public.cancel_event_registration(p_registration_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations;e public.events;n public.event_registrations;begin if auth.uid() is null or not public.has_role(array['administrator']) then raise exception 'forbidden';end if;select * into r from public.event_registrations where id=p_registration_id for update;if not found or r.status in('cancelled','refunded') then return;end if;select * into e from public.events where id=r.event_id for update;update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where id=r.id;perform public.enqueue_event_mail('event:'||r.id::text||':cancelled','event-cancelled',r.email,e.title,e.slug);if e.price_ore=0 then select * into n from public.event_registrations where event_id=e.id and status='waitlisted' order by created_at for update skip locked limit 1;if found then update public.event_registrations set status='confirmed',ticket_code=upper(substr(replace(pg_catalog.gen_random_uuid()::text,'-',''),1,12)) where id=n.id;perform public.enqueue_event_mail('event:'||n.id::text||':promoted','event-registration',n.email,e.title,e.slug);end if;end if;end $$;
create function public.cancel_event(p_event_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare e public.events;r public.event_registrations;begin if not public.has_role(array['administrator']) then raise exception 'forbidden';end if;select * into e from public.events where id=p_event_id for update;if not found then raise exception 'event_missing';end if;update public.events set cancelled_at=clock_timestamp(),registration_open=false where id=e.id;for r in select * from public.event_registrations where event_id=e.id and status in('confirmed','waitlisted','payment_pending') for update loop update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where id=r.id;perform public.enqueue_event_mail('event:'||r.id::text||':event-cancelled','event-cancelled',r.email,e.title,e.slug);end loop;end $$;
create function public.create_event_practical_message(p_event_id uuid,p_request_id uuid,p_digest text,p_message text) returns table(message_id uuid,registration_id uuid,recipient text) language plpgsql security definer set search_path='' as $$ declare saved public.event_practical_messages;begin if not public.has_role(array['administrator']) then raise exception 'forbidden';end if;if p_digest !~ '^[a-f0-9]{64}$' or char_length(p_message) not between 1 and 10000 then raise exception 'invalid announcement';end if;insert into public.event_practical_messages(event_id,request_id,request_digest,message) values(p_event_id,p_request_id,p_digest,p_message) on conflict(event_id,request_id) do nothing returning * into saved;if not found then select * into saved from public.event_practical_messages where event_id=p_event_id and request_id=p_request_id for update;if saved.request_digest<>p_digest then raise exception 'request_conflict';end if;end if;return query select saved.id,r.id,r.email from public.event_registrations r where r.event_id=p_event_id and r.status='confirmed';end $$;
alter table public.articles enable row level security;alter table public.events enable row level security;alter table public.event_registrations enable row level security;alter table public.stripe_webhook_events enable row level security;alter table public.event_practical_messages enable row level security;
create policy articles_public on public.articles for select using(status='published' and published_at<=clock_timestamp());create policy articles_staff on public.articles for all to authenticated using(public.has_role(array['superadmin','administrator','editor'])) with check(public.has_role(array['superadmin','administrator','editor']));create policy events_public on public.events for select using(published and cancelled_at is null);create policy events_staff on public.events for all to authenticated using(public.has_role(array['superadmin','administrator'])) with check(public.has_role(array['superadmin','administrator']));create policy registrations_staff on public.event_registrations for all to authenticated using(public.has_role(array['superadmin','administrator'])) with check(public.has_role(array['superadmin','administrator']));create policy stripe_staff on public.stripe_webhook_events for select to authenticated using(public.has_role(array['superadmin','administrator']));create policy practical_messages_staff on public.event_practical_messages for all to authenticated using(public.has_role(array['superadmin','administrator'])) with check(public.has_role(array['superadmin','administrator']));
revoke all on public.articles,public.events,public.event_registrations,public.stripe_webhook_events,public.event_practical_messages from public,anon,authenticated;grant select,insert,update,delete on public.articles,public.events,public.event_registrations,public.stripe_webhook_events,public.event_practical_messages to authenticated;grant all on public.articles,public.events,public.event_registrations,public.stripe_webhook_events,public.event_practical_messages to service_role;
-- Paid registrations snapshot price/currency and use an attempt id. A checkout expires
-- after 30 minutes; capacity is reserved for 35 minutes to safely accept a delayed webhook.
alter table public.event_registrations add column booking_price_ore integer, add column booking_currency text, add column reservation_attempt_id uuid, add column amount_refunded integer not null default 0, add column refund_status text not null default 'none' check(refund_status in('none','partial','full')), add column refund_required boolean not null default false;
create or replace function public.check_in_event_ticket(p_ticket_code text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; begin if auth.uid() is null or not public.has_role(array['administrator']) then raise exception 'forbidden'; end if; select * into r from public.event_registrations where ticket_code=p_ticket_code for update; if not found or r.status<>'confirmed' then raise exception 'ticket_invalid'; end if; update public.event_registrations set checked_in_at=coalesce(checked_in_at,clock_timestamp()) where id=r.id returning * into r; return r; end $$;
create or replace function public.process_event_refund(p_stripe_event_id text,p_payment_intent_id text,p_amount_refunded integer,p_currency text,p_payload jsonb) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'charge.refunded',p_payload) on conflict do nothing; if not found then return; end if; select * into r from public.event_registrations where payment_intent_id=p_payment_intent_id for update; if not found then raise exception 'refund_reconcile'; end if; if r.booking_currency<>lower(p_currency) or p_amount_refunded<0 or p_amount_refunded>coalesce(r.booking_price_ore,0) then raise exception 'refund_mismatch'; end if; update public.event_registrations set amount_refunded=p_amount_refunded, refund_status=case when p_amount_refunded=coalesce(booking_price_ore,0) then 'full' else 'partial' end, status=case when p_amount_refunded=coalesce(booking_price_ore,0) then 'refunded' else status end where id=r.id; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
revoke all on function public.process_event_refund(text,text,integer,text,jsonb) from public,anon,authenticated; grant execute on function public.process_event_refund(text,text,integer,text,jsonb) to service_role;
revoke all on function public.check_in_event_ticket(text) from public,anon,authenticated; grant execute on function public.check_in_event_ticket(text) to authenticated,service_role;
revoke all on function public.set_editorial_events_updated_at(),public.enqueue_event_mail(text,text,text,text,text),public.register_free_event(text,text,text,text),public.begin_paid_event_registration(text,text,text),public.attach_paid_checkout(uuid,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text),public.process_event_refund(text,text,jsonb),public.check_in_event_ticket(text),public.cancel_event_registration(uuid),public.cancel_event(uuid),public.create_event_practical_message(uuid,uuid,text,text) from public,anon,authenticated;grant execute on function public.register_free_event(text,text,text,text),public.begin_paid_event_registration(text,text,text),public.attach_paid_checkout(uuid,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text),public.process_event_refund(text,text,jsonb),public.process_event_refund(text,text,integer,text,jsonb) to service_role;grant execute on function public.cancel_event_registration(uuid),public.cancel_event(uuid),public.create_event_practical_message(uuid,uuid,text,text),public.check_in_event_ticket(text) to authenticated;
-- Reservation state is deliberately longer than Stripe Checkout (35 vs 30 minutes).
-- A valid paid webhook in the five-minute buffer receives a ticket; later payment is
-- retained for an explicit refund workflow rather than disappearing.
create or replace function public.begin_paid_event_registration(p_event_slug text,p_email text,p_name text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare e public.events; r public.event_registrations; taken integer; attempt uuid := pg_catalog.gen_random_uuid(); begin select * into e from public.events where slug=p_event_slug for update; if not found or not e.published or not e.registration_open or e.cancelled_at is not null or e.starts_at<=clock_timestamp() or e.price_ore<=0 then raise exception 'registration_closed'; end if; update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where event_id=e.id and status='payment_pending' and reservation_expires_at<=clock_timestamp(); select * into r from public.event_registrations where event_id=e.id and email=lower(p_email) for update; if found and r.status='confirmed' then return r; end if; if found and r.status='payment_pending' and r.reservation_expires_at>clock_timestamp() then return r; end if; select count(*) into taken from public.event_registrations where event_id=e.id and (status='confirmed' or (status='payment_pending' and reservation_expires_at>clock_timestamp())); if e.capacity is not null and taken>=e.capacity then if found then update public.event_registrations set name=p_name,status='waitlisted',reservation_expires_at=null,checkout_session_id=null,payment_intent_id=null,reservation_attempt_id=null,cancelled_at=null where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status) values(e.id,lower(p_email),p_name,'waitlisted') returning * into r; end if; return r; end if; if found then update public.event_registrations set name=p_name,status='payment_pending',reservation_expires_at=clock_timestamp()+interval '35 minutes',reservation_attempt_id=attempt,checkout_session_id=null,payment_intent_id=null,booking_price_ore=e.price_ore,booking_currency=e.currency,cancelled_at=null,refund_required=false where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status,reservation_expires_at,reservation_attempt_id,booking_price_ore,booking_currency) values(e.id,lower(p_email),p_name,'payment_pending',clock_timestamp()+interval '35 minutes',attempt,e.price_ore,e.currency) returning * into r; end if; return r; end $$;
create or replace function public.attach_paid_checkout(p_registration_id uuid,p_attempt_id uuid,p_checkout_session_id text) returns void language plpgsql security definer set search_path='' as $$ begin update public.event_registrations set checkout_session_id=p_checkout_session_id where id=p_registration_id and status='payment_pending' and reservation_attempt_id=p_attempt_id and checkout_session_id is null and reservation_expires_at>clock_timestamp(); if not found then raise exception 'reservation_expired'; end if; end $$;
create or replace function public.process_paid_checkout(p_stripe_event_id text,p_registration_id uuid,p_checkout_session_id text,p_client_reference_id text,p_payment_intent_id text,p_amount integer,p_currency text,p_payload jsonb,p_ticket_code text) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; e public.events; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'checkout.session.completed',p_payload) on conflict do nothing; if not found then return; end if; select * into r from public.event_registrations where id=p_registration_id for update; if not found then raise exception 'checkout_mismatch'; end if; select * into e from public.events where id=r.event_id for update; if r.id::text<>p_client_reference_id or r.checkout_session_id<>p_checkout_session_id or r.booking_price_ore<>p_amount or r.booking_currency<>lower(p_currency) then raise exception 'checkout_mismatch'; end if; if r.status='payment_pending' and r.reservation_expires_at>clock_timestamp() then update public.event_registrations set status='confirmed',ticket_code=p_ticket_code,payment_intent_id=p_payment_intent_id,reservation_expires_at=null where id=r.id; perform public.enqueue_event_mail('event:'||r.id::text||':confirmed','event-registration',r.email,e.title,e.slug); else update public.event_registrations set status='cancelled',payment_intent_id=p_payment_intent_id,refund_required=true,cancelled_at=clock_timestamp(),reservation_expires_at=null where id=r.id; end if; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
revoke all on function public.attach_paid_checkout(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.attach_paid_checkout(uuid,uuid,text) to service_role;
revoke all on function public.begin_paid_event_registration(text,text,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text) from public,anon,authenticated; grant execute on function public.begin_paid_event_registration(text,text,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text) to service_role;
alter table public.events add column external_url text check(external_url is null or external_url ~ '^https://');
alter table public.articles add column author_name text;
create or replace function public.create_event_practical_message_and_queue(p_event_id uuid,p_request_id uuid,p_digest text,p_message text,p_mails jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare saved public.event_practical_messages; expected integer; supplied integer; item jsonb; registration_id uuid; recipient_email text;
begin
 if auth.uid() is null or not public.has_role(array['administrator']) then raise exception 'forbidden'; end if;
 if p_digest !~ '^[a-f0-9]{64}$' or char_length(p_message) not between 1 and 10000 or jsonb_typeof(p_mails)<>'array' then raise exception 'invalid announcement'; end if;
 select count(*) into expected from public.event_registrations where event_id=p_event_id and status='confirmed'; select count(*) into supplied from jsonb_array_elements(p_mails);
 if supplied<>expected or supplied>500 then raise exception 'recipient_snapshot_mismatch'; end if;
 insert into public.event_practical_messages(event_id,request_id,request_digest,message) values(p_event_id,p_request_id,p_digest,p_message) on conflict(event_id,request_id) do nothing returning * into saved;
 if not found then select * into saved from public.event_practical_messages where event_id=p_event_id and request_id=p_request_id for update; if saved.request_digest<>p_digest then raise exception 'request_conflict'; end if; return saved.id; end if;
 for item in select value from jsonb_array_elements(p_mails) loop
  registration_id := (item->>'registrationId')::uuid; recipient_email := lower(item->>'recipient');
  if item->>'key' !~ '^[A-Za-z0-9_:/.-]{8,200}$' or not (item->'data' ? 'v' and item->'data' ? 'iv' and item->'data' ? 'ciphertext' and item->'data' ? 'tag') then raise exception 'invalid announcement mail'; end if;
  perform 1 from public.event_registrations where id=registration_id and event_id=p_event_id and status='confirmed' and email=recipient_email; if not found then raise exception 'recipient_snapshot_mismatch'; end if;
  perform public.enqueue_queue_mail(item->>'key','event-practical-info',recipient_email,item->'data',clock_timestamp(),null);
 end loop; return saved.id;
end $$;
revoke all on function public.create_event_practical_message_and_queue(uuid,uuid,text,text,jsonb) from public,anon,authenticated; grant execute on function public.create_event_practical_message_and_queue(uuid,uuid,text,text,jsonb) to authenticated;
create or replace function public.prevent_event_capacity_overflow() returns trigger language plpgsql set search_path='' as $$ declare occupied integer; begin if new.capacity is not null then select count(*) into occupied from public.event_registrations where event_id=new.id and status in ('confirmed','payment_pending'); if new.capacity<occupied then raise exception 'capacity_below_existing_registrations'; end if; end if; return new; end $$;
create trigger events_capacity_safe before update of capacity on public.events for each row execute function public.prevent_event_capacity_overflow();
-- Checkout attempts are immutable accounting records. A later retry must never
-- overwrite the session that a delayed Stripe webhook refers to.
create table public.event_payment_attempts (id uuid primary key default pg_catalog.gen_random_uuid(),registration_id uuid not null references public.event_registrations(id) on delete cascade,reservation_attempt_id uuid not null,checkout_session_id text unique,price_ore integer not null,currency text not null,expires_at timestamptz not null,payment_intent_id text unique,status text not null default 'reserved' check(status in('reserved','paid','expired','refund_required','refunded')),amount_refunded integer not null default 0,created_at timestamptz not null default clock_timestamp(),unique(registration_id,reservation_attempt_id));
alter table public.event_payment_attempts enable row level security; revoke all on public.event_payment_attempts from public,anon,authenticated; grant all on public.event_payment_attempts to service_role;
create or replace function public.attach_paid_checkout(p_registration_id uuid,p_attempt_id uuid,p_checkout_session_id text) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; begin select * into r from public.event_registrations where id=p_registration_id for update; if not found or r.status<>'payment_pending' or r.reservation_attempt_id<>p_attempt_id or r.reservation_expires_at<=clock_timestamp() then raise exception 'reservation_expired'; end if; update public.event_registrations set checkout_session_id=p_checkout_session_id where id=r.id and checkout_session_id is null; if not found then raise exception 'checkout_already_attached'; end if; insert into public.event_payment_attempts(registration_id,reservation_attempt_id,checkout_session_id,price_ore,currency,expires_at) values(r.id,p_attempt_id,p_checkout_session_id,r.booking_price_ore,r.booking_currency,r.reservation_expires_at-interval '5 minutes'); end $$;
create or replace function public.process_paid_checkout(p_stripe_event_id text,p_registration_id uuid,p_checkout_session_id text,p_client_reference_id text,p_payment_intent_id text,p_amount integer,p_currency text,p_payload jsonb,p_ticket_code text) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; a public.event_payment_attempts; e public.events; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'checkout.session.completed',p_payload) on conflict do nothing; if not found then return; end if; select * into a from public.event_payment_attempts where registration_id=p_registration_id and checkout_session_id=p_checkout_session_id for update; if not found or p_client_reference_id<>p_registration_id::text or a.price_ore<>p_amount or a.currency<>lower(p_currency) then raise exception 'checkout_mismatch'; end if; select * into r from public.event_registrations where id=p_registration_id for update; select * into e from public.events where id=r.event_id for update; update public.event_payment_attempts set payment_intent_id=p_payment_intent_id where id=a.id; if r.status='payment_pending' and r.reservation_attempt_id=a.reservation_attempt_id and r.reservation_expires_at>clock_timestamp() then update public.event_registrations set status='confirmed',ticket_code=p_ticket_code,payment_intent_id=p_payment_intent_id,reservation_expires_at=null where id=r.id; update public.event_payment_attempts set status='paid' where id=a.id; perform public.enqueue_event_mail('event:'||r.id::text||':confirmed','event-registration',r.email,e.title,e.slug); else update public.event_payment_attempts set status='refund_required' where id=a.id; update public.event_registrations set refund_required=true where id=r.id; end if; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
create or replace function public.process_event_refund(p_stripe_event_id text,p_payment_intent_id text,p_amount_refunded integer,p_currency text,p_payload jsonb) returns void language plpgsql security definer set search_path='' as $$ declare a public.event_payment_attempts; r public.event_registrations; next_amount integer; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'charge.refunded',p_payload) on conflict do nothing; if not found then return; end if; select * into a from public.event_payment_attempts where payment_intent_id=p_payment_intent_id for update; if not found then raise exception 'refund_reconcile'; end if; if a.currency<>lower(p_currency) or p_amount_refunded<0 or p_amount_refunded>a.price_ore then raise exception 'refund_mismatch'; end if; next_amount:=greatest(a.amount_refunded,p_amount_refunded); update public.event_payment_attempts set amount_refunded=next_amount,status=case when next_amount=a.price_ore then 'refunded' else 'refund_required' end where id=a.id; select * into r from public.event_registrations where id=a.registration_id for update; if r.payment_intent_id=p_payment_intent_id then update public.event_registrations set amount_refunded=greatest(amount_refunded,next_amount),refund_status=case when greatest(amount_refunded,next_amount)>=coalesce(booking_price_ore,0) then 'full' else 'partial' end,status=case when greatest(amount_refunded,next_amount)>=coalesce(booking_price_ore,0) then 'refunded' else status end,refund_required=greatest(amount_refunded,next_amount)<coalesce(booking_price_ore,0) where id=r.id; end if; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
-- These old overloads bypass attempt snapshots and must not remain callable.
drop function public.attach_paid_checkout(uuid,text);
drop function public.process_event_refund(text,text,jsonb);
revoke all on function public.attach_paid_checkout(uuid,uuid,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text),public.process_event_refund(text,text,integer,text,jsonb) from public,anon,authenticated; grant execute on function public.attach_paid_checkout(uuid,uuid,text),public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text),public.process_event_refund(text,text,integer,text,jsonb) to service_role;
create or replace function public.flag_cancelled_paid_registration() returns trigger language plpgsql set search_path='' as $$ begin if new.status='cancelled' and old.status<>'cancelled' and exists(select 1 from public.event_payment_attempts where registration_id=new.id and status='paid') then update public.event_payment_attempts set status='refund_required' where registration_id=new.id and status='paid'; new.refund_required:=true; end if; return new; end $$;
create trigger registrations_cancelled_refund before update of status on public.event_registrations for each row execute function public.flag_cancelled_paid_registration();
-- Persist the attempt before calling Stripe. This closes the crash window between
-- checkout creation and attach; a signed webhook can bind the session later.
create or replace function public.begin_paid_event_registration(p_event_slug text,p_email text,p_name text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare e public.events; r public.event_registrations; taken integer; attempt uuid:=pg_catalog.gen_random_uuid(); begin select * into e from public.events where slug=p_event_slug for update; if not found or not e.published or not e.registration_open or e.cancelled_at is not null or e.starts_at<=clock_timestamp() or e.price_ore<=0 then raise exception 'registration_closed'; end if; update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where event_id=e.id and status='payment_pending' and reservation_expires_at<=clock_timestamp(); select * into r from public.event_registrations where event_id=e.id and email=lower(p_email) for update; if found and r.status='confirmed' then return r; end if; if found and r.status='payment_pending' and r.reservation_expires_at>clock_timestamp() then return r; end if; select count(*) into taken from public.event_registrations where event_id=e.id and (status='confirmed' or(status='payment_pending' and reservation_expires_at>clock_timestamp())); if e.capacity is not null and taken>=e.capacity then if found then update public.event_registrations set name=p_name,status='waitlisted',reservation_expires_at=null,reservation_attempt_id=null,checkout_session_id=null,payment_intent_id=null,cancelled_at=null where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status) values(e.id,lower(p_email),p_name,'waitlisted') returning * into r; end if; return r; end if; if found then update public.event_registrations set name=p_name,status='payment_pending',reservation_expires_at=clock_timestamp()+interval '35 minutes',reservation_attempt_id=attempt,checkout_session_id=null,payment_intent_id=null,booking_price_ore=e.price_ore,booking_currency=e.currency,cancelled_at=null,refund_required=false where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status,reservation_expires_at,reservation_attempt_id,booking_price_ore,booking_currency) values(e.id,lower(p_email),p_name,'payment_pending',clock_timestamp()+interval '35 minutes',attempt,e.price_ore,e.currency) returning * into r; end if; insert into public.event_payment_attempts(registration_id,reservation_attempt_id,price_ore,currency,expires_at) values(r.id,attempt,r.booking_price_ore,r.booking_currency,r.reservation_expires_at-interval '5 minutes'); return r; end $$;
create or replace function public.attach_paid_checkout(p_registration_id uuid,p_attempt_id uuid,p_checkout_session_id text) returns void language plpgsql security definer set search_path='' as $$ declare a public.event_payment_attempts; begin select * into a from public.event_payment_attempts where registration_id=p_registration_id and reservation_attempt_id=p_attempt_id for update; if not found or a.expires_at<=clock_timestamp() then raise exception 'reservation_expired'; end if; if a.checkout_session_id is not null and a.checkout_session_id<>p_checkout_session_id then raise exception 'checkout_already_attached'; end if; update public.event_payment_attempts set checkout_session_id=p_checkout_session_id where id=a.id and checkout_session_id is null; update public.event_registrations set checkout_session_id=p_checkout_session_id where id=p_registration_id and reservation_attempt_id=p_attempt_id and checkout_session_id is null; end $$;
drop function public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text);
create function public.process_paid_checkout(p_stripe_event_id text,p_registration_id uuid,p_checkout_session_id text,p_client_reference_id text,p_payment_intent_id text,p_amount integer,p_currency text,p_payload jsonb,p_ticket_code text,p_attempt_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; a public.event_payment_attempts; e public.events; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'checkout.session.completed',p_payload) on conflict do nothing; if not found then return; end if; select * into a from public.event_payment_attempts where registration_id=p_registration_id and reservation_attempt_id=p_attempt_id for update; if not found or p_client_reference_id<>p_registration_id::text or a.price_ore<>p_amount or a.currency<>lower(p_currency) or (a.checkout_session_id is not null and a.checkout_session_id<>p_checkout_session_id) then raise exception 'checkout_mismatch'; end if; update public.event_payment_attempts set checkout_session_id=p_checkout_session_id,payment_intent_id=p_payment_intent_id where id=a.id; select * into r from public.event_registrations where id=p_registration_id for update; select * into e from public.events where id=r.event_id for update; if r.status='payment_pending' and r.reservation_attempt_id=a.reservation_attempt_id and r.reservation_expires_at>clock_timestamp() then update public.event_registrations set status='confirmed',ticket_code=p_ticket_code,payment_intent_id=p_payment_intent_id,reservation_expires_at=null where id=r.id; update public.event_payment_attempts set status='paid' where id=a.id; perform public.enqueue_event_mail('event:'||r.id::text||':confirmed','event-registration',r.email,e.title,e.slug); else update public.event_payment_attempts set status='refund_required' where id=a.id; if r.reservation_attempt_id=a.reservation_attempt_id then update public.event_registrations set refund_required=true where id=r.id; end if; end if; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
revoke all on function public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text,uuid) from public,anon,authenticated; grant execute on function public.process_paid_checkout(text,uuid,text,text,text,integer,text,jsonb,text,uuid) to service_role;
create or replace function public.process_paid_checkout(p_stripe_event_id text,p_registration_id uuid,p_checkout_session_id text,p_client_reference_id text,p_payment_intent_id text,p_amount integer,p_currency text,p_payload jsonb,p_ticket_code text,p_attempt_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare r public.event_registrations; a public.event_payment_attempts; e public.events; begin insert into public.stripe_webhook_events(stripe_event_id,event_type,payload) values(p_stripe_event_id,'checkout.session.completed',p_payload) on conflict do nothing; if not found then return; end if; select * into a from public.event_payment_attempts where registration_id=p_registration_id and reservation_attempt_id=p_attempt_id for update; if not found or p_client_reference_id<>p_registration_id::text or a.price_ore<>p_amount or a.currency<>lower(p_currency) or (a.checkout_session_id is not null and a.checkout_session_id<>p_checkout_session_id) then raise exception 'checkout_mismatch'; end if; if a.status in('paid','refunded') then if a.checkout_session_id=p_checkout_session_id and a.payment_intent_id=p_payment_intent_id then update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; return; end if; raise exception 'checkout_conflict'; end if; if a.payment_intent_id is not null and a.payment_intent_id<>p_payment_intent_id then raise exception 'checkout_conflict'; end if; update public.event_payment_attempts set checkout_session_id=p_checkout_session_id,payment_intent_id=p_payment_intent_id where id=a.id; select * into r from public.event_registrations where id=p_registration_id for update; select * into e from public.events where id=r.event_id for update; if r.status='payment_pending' and r.reservation_attempt_id=a.reservation_attempt_id and r.reservation_expires_at>clock_timestamp() then update public.event_registrations set status='confirmed',ticket_code=p_ticket_code,payment_intent_id=p_payment_intent_id,reservation_expires_at=null where id=r.id; update public.event_payment_attempts set status='paid' where id=a.id; perform public.enqueue_event_mail('event:'||r.id::text||':confirmed','event-registration',r.email,e.title,e.slug); else update public.event_payment_attempts set status='refund_required' where id=a.id; if r.reservation_attempt_id=a.reservation_attempt_id then update public.event_registrations set refund_required=true where id=r.id; end if; end if; update public.stripe_webhook_events set processed_at=clock_timestamp() where stripe_event_id=p_stripe_event_id; end $$;
create or replace function public.begin_paid_event_registration(p_event_slug text,p_email text,p_name text) returns public.event_registrations language plpgsql security definer set search_path='' as $$ declare e public.events; r public.event_registrations; taken integer; attempt uuid:=pg_catalog.gen_random_uuid(); has_registration boolean:=false; begin select * into e from public.events where slug=p_event_slug for update; if not found or not e.published or not e.registration_open or e.cancelled_at is not null or e.starts_at<=clock_timestamp() or e.price_ore<=0 then raise exception 'registration_closed'; end if; update public.event_registrations set status='cancelled',cancelled_at=clock_timestamp() where event_id=e.id and status='payment_pending' and reservation_expires_at<=clock_timestamp(); select * into r from public.event_registrations where event_id=e.id and email=lower(p_email) for update; has_registration:=found; if has_registration and r.status='confirmed' then return r; end if; if has_registration and r.status='payment_pending' and r.reservation_expires_at>clock_timestamp() then return r; end if; select count(*) into taken from public.event_registrations where event_id=e.id and (status='confirmed' or(status='payment_pending' and reservation_expires_at>clock_timestamp())); if e.capacity is not null and taken>=e.capacity then if has_registration then update public.event_registrations set name=p_name,status='waitlisted',reservation_expires_at=null,reservation_attempt_id=null,checkout_session_id=null,payment_intent_id=null,cancelled_at=null where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status) values(e.id,lower(p_email),p_name,'waitlisted') returning * into r; end if; return r; end if; if has_registration then update public.event_registrations set name=p_name,status='payment_pending',reservation_expires_at=clock_timestamp()+interval '35 minutes',reservation_attempt_id=attempt,checkout_session_id=null,payment_intent_id=null,booking_price_ore=e.price_ore,booking_currency=e.currency,cancelled_at=null,refund_required=false where id=r.id returning * into r; else insert into public.event_registrations(event_id,email,name,status,reservation_expires_at,reservation_attempt_id,booking_price_ore,booking_currency) values(e.id,lower(p_email),p_name,'payment_pending',clock_timestamp()+interval '35 minutes',attempt,e.price_ore,e.currency) returning * into r; end if; insert into public.event_payment_attempts(registration_id,reservation_attempt_id,price_ore,currency,expires_at) values(r.id,attempt,r.booking_price_ore,r.booking_currency,r.reservation_expires_at-interval '5 minutes'); return r; end $$;
